package com.railyatra.railway.repository;
import java.time.LocalDate; import java.util.Optional; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import com.railyatra.railway.domain.SeatInventory;
public interface SeatInventoryRepository extends JpaRepository<SeatInventory,Long>{Optional<SeatInventory> findByTrainIdAndJourneyDateAndTrainClassIdAndQuota(Long trainId,LocalDate date,Long classId,String quota); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select i from SeatInventory i where i.id=:id") Optional<SeatInventory> findByIdForUpdate(@Param("id") Long id);}
